import React from 'react';

import { TimeseriesExploreKeyboardOverlay } from './TimeseriesExploreKeyboardOverlay.js';
import { TimeseriesExploreOverlay } from './TimeseriesExploreOverlay.js';
import { useZoomState } from '../../../hooks/store/selectors.js';
import { useChartInteractions } from '../../../hooks/useChartInteractions.js';

export const TimeseriesExploreMode = () => {
  const { activeKeyboardMode } = useZoomState();
  const { zoomX } = useChartInteractions();
  const isZoomXEnabled = zoomX?.enabled;

  return isZoomXEnabled && activeKeyboardMode ? (
    <TimeseriesExploreKeyboardOverlay />
  ) : (
    <TimeseriesExploreOverlay />
  );
};
